const axios = require('axios');

async function getViesnapInfo(url) {
  try {
    const response = await axios.post('https://api.viesnap.com/info', {
      url: url
    }, {
      headers: {
        'Content-Type': 'application/json'
      }
    });

    const data = response.data;

    const replyMessage = `
Source: ${data.source}
Original URL: ${data.original_url}
Title: ${data.title}
Author: ${data.author}
Description: ${data.description}
Duration: ${data.duration}
Thumbnail: ${data.thumbnail}
View Count: ${data.view_count}
`;

    return replyMessage;
  } catch (error) {
    console.error('Error fetching Viesnap info:', error.message);
    return 'Terjadi kesalahan saat mengambil informasi.';
  }
}

